mapper.select:
SELECT NVL(SUM(mpr.PNL_QTY), 0) AS "allocatedPnl",
       NVL(SUM(mpr.PCS_QTY), 0) AS "allocatedPcs"
FROM MES_PRODUCTION_RECORD mpr
WHERE mpr.LOT_CODE = #{lotCode}


      AND mpr.RECORD_TYPE = 'EQUIPMENT'
      AND mpr.EQUIPMENT_ID = #{equipmentId}


      AND mpr.RECORD_TYPE = 'MANUAL'


  AND mpr.STATUS IN ('INPROGRESS', 'COMPLETED')

    AND mpr.ID <> #{excludeRecordId}

  AND (
    (#{stationId} IS NOT NULL AND (
        mpr.WORKSTATION_ID = #{stationId}
        OR (mpr.WORKSTATION_ID IS NULL
            AND UPPER(TRIM(mpr.LOT_SITE)) = UPPER(TRIM(#{lotSite})))
    ))
    OR
    (#{stationId} IS NULL
        AND UPPER(TRIM(mpr.LOT_SITE)) = UPPER(TRIM(#{lotSite})))
  )

SELECT *
FROM MES_PRODUCTION_RECORD
WHERE employee_id = #{employeeId}
  AND record_type = #{recordType}
  AND status = 'INPROGRESS'
  AND ROWNUM = 1

SELECT prp.PARAM_KEY as "paramKey", prp.PARAM_VALUE as "paramValue"
FROM MES_RECORD_PARAMETER prp
JOIN MES_PRODUCTION_RECORD mpr ON prp.RECORD_ID = mpr.ID
WHERE mpr.EQUIPMENT_ID = #{equipmentId}
  AND mpr.LOT_CODE IN (
      SELECT LOTNAME FROM PRP_LOT WHERE PRODUCTPN = #{productCode}
  )
  AND mpr.START_TIME >= #{shiftStart}
  AND mpr.START_TIME < #{shiftEnd}
  AND mpr.ID = (
      SELECT ID FROM (
          SELECT ID FROM MES_PRODUCTION_RECORD
          WHERE EQUIPMENT_ID = #{equipmentId}
            AND LOT_CODE IN (
                SELECT LOTNAME FROM PRP_LOT WHERE PRODUCTPN = #{productCode}
            )
            AND START_TIME >= #{shiftStart}
            AND START_TIME < #{shiftEnd}
          ORDER BY START_TIME DESC
      ) WHERE ROWNUM = 1
  )
